cases.extended:
{
  "schemaVersion": 1,
  "enabled": true,
  "targets": ["client", "server"],
  "settings": {
    "noResourceCost": {
      "value": false,
      "label": "No Recipe Resource Costs",
      "control": "checkbox",
      "applyAt": "restart",
      "restartRequired": true
    },
    "infiniteItemUse": {
      "value": false,
      "label": "No Item Consumption",
      "control": "checkbox",
      "applyAt": "live",
      "restartRequired": false
    },
    "productionTimeMode": {
      "value": "original",
      "control": "select",
      "options": {
        "original": "Original recipe times",
        "fixed": "One shared time"
      }
    },
    "productionSeconds": {
      "value": 3,
      "label": "Production Time in Seconds",
      "control": "slider",
      "min": 1,
      "max": 900,
      "step": 1,
      "enabledWhen": {
        "setting": "productionTimeMode",
        "equals": "fixed"
      },
      "restartRequired": false
    }
  }
}

